const root = process.argv[2];
const { canEdit } = require(root + '/src/auth');
const { updateDoc, deleteDoc } = require(root + '/src/routes');
const owned = { id: 'd1', ownerId: 'u1' }, orphan = { id: 'd2' };
const cases = [
 ['editor, owned doc', { id: 'e', role: 'editor' }, owned],
 ['editor, orphan doc', { id: 'e', role: 'editor' }, orphan],
 ['admin', { id: 'a', role: 'admin' }, owned],
 ['owner viewer', { id: 'u1', role: 'viewer' }, owned],
 ['other viewer', { id: 'u2', role: 'viewer' }, owned],
 ['id-less viewer, orphan doc', { role: 'viewer' }, orphan],
 ['id-less user {} , orphan doc', {}, orphan],
 ['null id viewer, ownerId null', { id: null, role: 'viewer' }, { id: 'd3', ownerId: null }],
 ['null user', null, owned],
 ['role Editor (case)', { id: 'x', role: 'Editor' }, owned],
];
for (const [n, u, d] of cases) console.log(n.padEnd(32), canEdit(u, d));
const store = new Map([['d2', orphan]]);
console.log('deleteDoc id-less viewer on orphan:', deleteDoc({ role: 'viewer' }, orphan, store).status);
EOF
echo "== change"; node $S/probe.js $PWD; echo "== base"; node $S/probe.js $S/base

